import re

def find_emails(text):
    emails = []
    pattern = r'[\w+\.-]+@[\w\.-]+'
    for match in re.finditer(pattern, text, re.MULTILINE):
        email = match.group(0)
        if email not in emails:
            emails.append(email)

    return emails

