def is_liked(image_id, user_id):
    cursor.execute("SELECT liked_by FROM images WHERE id = %s", [image_id])
    liked_by = cursor.fetchone()[0]
    return user_id in liked_by

def toggle_like(image_id, user_id):
    if is_liked(image_id, user_id):
        cursor.execute("UPDATE images SET likes = likes - 1 WHERE id = %s", [image_id])
        cursor.execute("UPDATE images SET liked_by = array_remove(liked_by, %s) WHERE id = %s", [user_id, image_id])
    else:
        cursor.execute("UPDATE images SET likes = likes + 1 WHERE id = %s", [image_id])
        cursor.execute("UPDATE images SET liked_by = array_append(liked_by, %s) WHERE id = %s", [user_id, image_id])

