def check_email(email):
    match = re.fullmatch(r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b', email)
    if not match:
        raise ValueError(f"Invalid email address: {email}")

    domain = email.split('@')[1]
    tlds = ['com', 'org', 'net']

    if domain in tlds:
        raise ValueError,f"Invalid domain in email address: {domain}")
    return match.group(0)

