class Config:
    def __init__(self):
        self.settings = {}

    def get(self, key):
        return self.settings.get(key)

def create_config(file_path):

    with open(file_path, "r") as f:
        lines = f.readlines()

    config = Config()
    for line in lines:
        if "=" not in line or line.startswith("#"):
            continue

        key, value = line.split("=")
        key = key.strip()
        value = value.strip()
        config.settings[key] = value

    return config

