def get_latest_version(repo_path):
    latest = None
    for root, dirs, files in os.walk(repo_path):
        for f in files:
            if f == 'VERSION':
                version_path = os.path.join(root, f)
                with open(version_path, 'r') as f:
                    version = f.read().strip()
                if latest is None or version > latest:
                    latest = version
    return latest

