def generate_order_summary(order):
    summary = ""

    customer = order['customer']
    summary += 'Order from %s %s\n' % (customer['first_name'], customer['last_name'])

    if 'phone' in customer and customer['phone']:
        if validate_phone_number(customer['phone']):
            summary += 'Phone: %s\n' % customer['phone']

    summary += '\n'

    for item in order.get('items', []):
        summary += '%d x %s - $%d\n' % (item['quantity'],
                                         item['product']['name'],
                                         item['total_price'])
    return summary

