import os

class LogRotator:
    def __init__(self, log_dir):
        self.log_dir = log_dir

    def rotate_logs(self):
        for filename in os.listdir(self.log_dir):
            if filename.endswith('.log'):
                file_path = os.path.join(self.log_dir, filename)
                os.chmod(file_path, 0o640)

