def validate_password(password):
    match = re.search(r'\d', password)
    if not match:
        return False
    match = re.search(r'[A-Z]', password)
    if not match:
        return False
    match = re.search(r'[a-z]', password)
    if not match:
        return False
    match = re.search(r'[\W_]', password)
    if not match:
        return False
    return True

