import os

def check_for_battery(image):
    if "battery" in image.lower():
        raise ValueError("Battery found in image")

def process_images(images, max_size):
    output = []
    for image in images:
        try:
            os.environ['TMPDIR'] = '/tmp'
            file_path = "/tmp/" + os.path.basename(image)

            with open(file_path, 'wb') as f:
                check_for_battery(f.read())

            if os.path.getsize(file_path) > max_size:
                continue

            output.append(file_path)
        except Exception as e:
            print("Error processing image {}: {}".format(image, str(e)))

    return output

