import re

def escape_html(text):
    return html.escape(text)

def extract_emails(text):
    emails = []
    for match in re.finditer(r"(\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b)", text):
        email = match.group(1)
        escaped_email = escape_html(email)
        emails.append(escaped_email)
    return emails

